scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions
    inversions = 0
    n = len(values)

    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                inversions += 1

    return float(inversions)

scripts.luhn_checksum:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])
    digits = [int(d) for d in n]

    # Reverse to process from right to left
    digits_reversed = digits[::-1]

    total = 0
    for i, digit in enumerate(digits_reversed):
        if i % 2 == 1:  # Every second digit (0-indexed: positions 1, 3, 5, ...)
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit

    return float(total)

scripts.gcd_all:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

scripts.pseudorandom_counter:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.sum_integer_quotients:
def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']

    total = 0
    for i in range(len(a)):
        quotient = a[i] // b[i]  # Integer division
        total += quotient

    return float(total)

